}

export function createMcpToolFailureEvent(
	toolName: string,
	errorType: ErrorType,
	diagnostic: {
		category: string;
		code?: string;
		status?: number;
		method?: string;
		endpoint?: string;
		execution?: StructuredExecutionProjection;
	},
): McpToolFailureEvent {
	const execution = diagnostic.execution;
	return {
		event: "mcp.tool.failure",
		"mcp.tool.name": toolName,
		"error.type": errorType,
		"error.category": diagnostic.category,
		...(diagnostic.code ? { "error.code": diagnostic.code } : {}),
		...(diagnostic.status !== undefined
			? { "http.status_code": diagnostic.status }
			: {}),
		...(diagnostic.method ? { "http.method": diagnostic.method } : {}),
		...(diagnostic.endpoint
			? { "hevy.api.endpoint": diagnostic.endpoint }
			: {}),
		...(execution
			? {
					"hevy.api.outcome": execution.outcome,
					"hevy.api.phase": execution.phase,
					"hevy.api.operation_safety": execution.operation_safety,
					"hevy.api.commit_state": execution.commit_state,
					"hevy.api.safe_to_retry": execution.safe_to_retry,
				}
			: {}),
	};
}

/** Structured debug context containing only bounded, safe metadata. */
export interface ErrorDebugContext {
	sourceContext?: string;
	originalErrorMessage: string;
	errorCode?: string;
	errorType: ErrorType;
	execution?: StructuredExecutionProjection;
	axios?: {
		status?: number;
		statusText?: string;
		method?: string;
		url?: string;
	};
}

/**
 * Create a standardized error response for MCP tools
 *
 * @param error - The error object or message
 * @param context - Optional context information about where the error occurred
 * @returns A formatted MCP tool response with error information
 */
export function createErrorResponse(
	error: unknown,
	context?: string,
): McpToolResponse {
	const policy = resolveErrorPolicy(
		error,
		"The request failed unexpectedly. Please try again.",
		HEVY_CLIENT_NOT_INITIALIZED_ERROR,
	);
	const { diagnostic } = policy;
	const execution = createExecutionProjection(diagnostic);
	const axiosErrorContext: ErrorDebugContext["axios"] | null =
		diagnostic.status !== undefined ||
		diagnostic.method !== undefined ||
		diagnostic.endpoint !== undefined
			? {
					status: diagnostic.status,
					method: diagnostic.method,
					url: diagnostic.endpoint,
				}
			: null;
	const errorContext: ErrorDebugContext = {
		sourceContext: context,
		originalErrorMessage: `${diagnostic.category} occurred`,
		errorCode: diagnostic.code,
		errorType: policy.type,
		execution,
		axios: axiosErrorContext ?? undefined,
	};
	const contextPrefix = context ? `[${context}] ` : "";
	const formattedMessage = `${contextPrefix}Error: ${policy.message}`;
	console.error(
		JSON.stringify(
			createMcpToolFailureEvent(context || "unknown", policy.type, {
				...diagnostic,
				execution,
			}),
		),
	);

	return {
		content: [{ type: "text" as const, text: formattedMessage }],
		isError: true,
		errorContext,
		structuredContent: { error: execution },
		errorOutcome: execution,
	};
}

/**
 * Wrap an async function with standardized error handling
 *
 * @param fn - The async function to wrap
 * @param context - Context information for error messages
 * @returns A function that catches errors and returns standardized error responses
 */
export function withErrorHandling<TParams extends Record<string, unknown>>(
	fn: (
		args: TParams,
		context?: ToolExecutionContext,
	) => Promise<McpToolResponse>,
	context: string,
	onError?: (error: unknown, context: string, argumentKeyCount: number) => void,
): (
	args: Record<string, unknown>,
	context?: ToolExecutionContext,
) => Promise<McpToolResponse> {
	return async (
		rawArgs: Record<string, unknown>,
		requestContext?: ToolExecutionContext,
	) => {
		const normalizedArgs = rawArgs ?? {};
		try {
			return await fn(normalizedArgs as TParams, requestContext);
		} catch (error) {
			try {
				onError?.(error, context, Object.keys(normalizedArgs).length);
			} catch {
				console.error("MCP error observer failure", {
					category: "ObserverError",
				});
			}

			return createErrorResponse(error, context);
		}
	};
}

import { z } from "zod";

type JsonSchema = Record<string, unknown>;

function isRecord(value: unknown): value is JsonSchema {
	return value !== null && typeof value === "object" && !Array.isArray(value);
}

function isNullSchema(value: unknown): value is JsonSchema {
	return (
		isRecord(value) && value.type === "null" && Object.keys(value).length === 1
	);
}

function compactNullableSchema(value: unknown): unknown {
	if (Array.isArray(value)) {
		return value.map(compactNullableSchema);
	}
	if (!isRecord(value)) {
		return value;
	}

	const anyOf = value.anyOf;
	if (Array.isArray(anyOf) && anyOf.length === 2) {
		const nullableBranch = anyOf.find(isNullSchema);
		const valueBranch = anyOf.find((branch) => !isNullSchema(branch));
		if (
			nullableBranch !== undefined &&
			isRecord(valueBranch) &&
			typeof valueBranch.type === "string"
		) {
			const { anyOf: _anyOf, ...metadata } = value;
			return compactNullableSchema({
				...valueBranch,
				...metadata,
				type: [valueBranch.type, "null"],
			});
		}
	}

	return Object.fromEntries(
		Object.entries(value).map(([key, nested]) => [
			key,
			compactNullableSchema(nested),
		]),
	);
}

function omitOutputObjectRestrictions(value: unknown): unknown {
	if (Array.isArray(value)) {
		return value.map(omitOutputObjectRestrictions);
	}
	if (!isRecord(value)) {
		return value;
	}
	return Object.fromEntries(
		Object.entries(value)
			.filter(
				([key, nested]) => key !== "additionalProperties" || nested !== false,
			)
			.map(([key, nested]) => [key, omitOutputObjectRestrictions(nested)]),
	);
}

function convertSchema(
	schema: z.ZodTypeAny,
	io: "input" | "output",
): JsonSchema {
	const converted = z.toJSONSchema(schema, {
		target: "draft-2020-12",
		io,
	});
	if (!isRecord(converted)) {
		throw new Error("Zod emitted a non-object root schema");
	}
	const compacted = compactNullableSchema(converted);
	if (!isRecord(compacted)) {
		throw new Error("Nullable schema compaction changed the root schema");
	}
	const output =
		io === "output" ? omitOutputObjectRestrictions(compacted) : compacted;
	if (!isRecord(output)) {
		throw new Error("Output schema compaction changed the root schema");
	}
	delete output.$schema;
	return output;
}

/**
 * Keep Zod validation while advertising a compact JSON Schema.
 *
 * Zod emits nullable values as `anyOf`; draft 2020-12 also permits a type
 * array. The MCP wire envelope does not need a repeated `$schema` marker, and
 * structured output is validated by the original Zod schema before sending.
 */
export function compactJsonSchema<TSchema extends z.ZodTypeAny>(
	schema: TSchema,
): TSchema {
	let inputSchema: JsonSchema | undefined;
	let outputSchema: JsonSchema | undefined;
	Object.defineProperty(schema["~standard"], "jsonSchema", {
		configurable: true,
		value: {
			input: () => {
				inputSchema ??= convertSchema(schema, "input");
				return inputSchema;
			},
			output: () => {
				outputSchema ??= convertSchema(schema, "output");
				return outputSchema;
			},
		},
		writable: true,
	});
	return schema;
}

