export function bucketCount(value: number): ResultCountBucket {
	if (!Number.isFinite(value) || value <= 0) return "0";
	if (value === 1) return "1";
	if (value <= 10) return "2-10";
	if (value <= 50) return "11-50";
	return "51+";
}

