	result: object,
	telemetry: ToolResultTelemetry | undefined,
): void {
	if (telemetry) resultTelemetry.set(result, telemetry);
}

export function getResultTelemetry(
	result: object,
): ToolResultTelemetry | undefined {
	return resultTelemetry.get(result);
}

